const cx=W()/2, cy=H()/2;
let t=0;
const minR=Math.min(W(),H())*0.30;
const maxR=Math.min(W(),H())*0.52;
const N=90;
const leaves=[];
for(let i=0;i<N;i++){
  leaves.push({
    angle: Math.random()*Math.PI*2,
    speed: 0.0015+Math.random()*0.0015,
    freq: 0.3+Math.random()*0.5,
    phase: Math.random()*Math.PI*2,
    size: 4+Math.random()*6,
    spin: Math.random()*Math.PI*2,
    spinSpeed:(Math.random()-0.5)*0.02,
    trail: [],
    colorIdx: Math.floor(Math.random()*3)
  });
}
const trufX=W()*0.78, trufY=H()*0.74;
const trufR=Math.min(W(),H())*0.13;
const dust=[];
for(let i=0;i<50;i++){
  dust.push({
    a:Math.random()*Math.PI*2,
    r: trufR*(0.3+Math.random()*1.4),
    speed:0.0008+Math.random()*0.0012,
    size:1+Math.random()*2,
    alpha:0.3+Math.random()*0.5
  });
}
function hexToRgb(hex){
  const n=parseInt(hex.slice(1),16);
  return [(n>>16)&255,(n>>8)&255,n&255];
}
const rgbPal=PALETTE.map(hexToRgb);
function frame(){
  const w=W(), h=H();
  ctx.clearRect(0,0,w,h);
  t+=1;

  const g=ctx.createRadialGradient(trufX,trufY,trufR*0.1,trufX,trufY,trufR*2.2);
  g.addColorStop(0, `rgba(${rgbPal[1][0]},${rgbPal[1][1]},${rgbPal[1][2]},0.35)`);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle=g;
  ctx.beginPath();
  ctx.arc(trufX,trufY,trufR*2.2,0,Math.PI*2);
  ctx.fill();

  const tg=ctx.createRadialGradient(trufX-trufR*0.3,trufY-trufR*0.3,trufR*0.1,trufX,trufY,trufR);
  tg.addColorStop(0, PALETTE[1]);
  tg.addColorStop(1, PALETTE[0]);
  ctx.save();
  ctx.shadowColor=`rgba(${rgbPal[1][0]},${rgbPal[1][1]},${rgbPal[1][2]},0.5)`;
  ctx.shadowBlur=30;
  ctx.fillStyle=tg;
  ctx.beginPath();
  ctx.arc(trufX,trufY,trufR,0,Math.PI*2);
  ctx.fill();
  ctx.restore();

  ctx.save();
  for(let i=0;i<24;i++){
    const ang=i/24*Math.PI*2+t*0.001;
    const rr=trufR*(0.3+0.6*((i%5)/5));
    const dx=trufX+Math.cos(ang)*rr;
    const dy=trufY+Math.sin(ang)*rr*0.9;
    ctx.fillStyle=`rgba(${rgbPal[2][0]},${rgbPal[2][1]},${rgbPal[2][2]},0.25)`;
    ctx.beginPath();
    ctx.arc(dx,dy,1.5,0,Math.PI*2);
    ctx.fill();
  }
  ctx.restore();

  dust.forEach(d=>{
    d.a+=d.speed;
    const x=trufX+Math.cos(d.a)*d.r;
    const y=trufY+Math.sin(d.a)*d.r*0.85 - Math.sin(t*0.01)*2;
    ctx.beginPath();
    ctx.fillStyle=`rgba(${rgbPal[2][0]},${rgbPal[2][1]},${rgbPal[2][2]},${d.alpha})`;
    ctx.arc(x,y,d.size,0,Math.PI*2);
    ctx.fill();
  });

  leaves.forEach(leaf=>{
    leaf.angle+=leaf.speed;
    leaf.spin+=leaf.spinSpeed;
    const rad=minR+(maxR-minR)*(0.5+0.5*Math.sin(t*0.004*leaf.freq+leaf.phase));
    const x=cx+Math.cos(leaf.angle)*rad;
    const y=cy+Math.sin(leaf.angle)*rad*0.72;

    leaf.trail.push({x,y});
    if(leaf.trail.length>14) leaf.trail.shift();

    for(let j=0;j<leaf.trail.length;j++){
      const p=leaf.trail[j];
      const alpha=(j/leaf.trail.length)*0.35;
      const c=rgbPal[leaf.colorIdx];
      ctx.beginPath();
      ctx.fillStyle=`rgba(${c[0]},${c[1]},${c[2]},${alpha})`;
      ctx.arc(p.x,p.y, leaf.size*0.35*(j/leaf.trail.length), 0, Math.PI*2);
      ctx.fill();
    }

    ctx.save();
    ctx.translate(x,y);
    ctx.rotate(leaf.spin);
    const c=rgbPal[leaf.colorIdx];
    ctx.fillStyle=`rgba(${c[0]},${c[1]},${c[2]},0.75)`;
    ctx.beginPath();
    ctx.ellipse(0,0, leaf.size, leaf.size*0.4, 0, 0, Math.PI*2);
    ctx.fill();
    ctx.restore();
  });

  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
